import { BundlerContext, Target } from '@teambit/bundler';
import type { Configuration } from '@rspack/core';

export type RspackBundlerOptions = {
  /**
   * path to load the rspack instance from
   */
  rspackModulePath?: string;

  /**
   * name of the rspack bundler.
   */
  name?: string;

  /**
   * the configuration for the rspack compiler.
   */
  config?: Configuration | any;

  /**
   * array of targets to bundle.
   */
  targets: Target[];

  /**
   * array of transformers to apply on rspack config.
   */
  transformers: any[];

  /**
   * bundler context
   */
  bundlerContext: BundlerContext;
};
